133	    /**
134	     * Determine how many offspring are produced this step.
135	     */
136	    protected final int calculateBirths(int age, int breedingAge,
137	                                        double breedingProbability, int maxLitterSize)
138	    {
139	        if(age >= breedingAge && rand.nextDouble() <= breedingProbability) {
140	            return rand.nextInt(maxLitterSize) + 1;
141	        }
142	        return 0;
143	    }
