145	    /**
146	     * Add offspring into available adjacent locations.
147	     */
148	    protected final void addOffspring(List<Animal> newAnimals, int births,
149	                                      OffspringFactory offspringFactory)
150	    {
151	        Field field = getField();
152	        List<Location> free = freeAdjacentLocations();
153	        for(int b = 0; b < births && free.size() > 0; b++) {
154	            Location location = free.remove(0);
155	            newAnimals.add(offspringFactory.create(field, location));
156	        }
157	    }
