159	    /**
160	     * Check whether a mate of the same species is nearby.
161	     */
162	    protected final boolean hasAdjacentMate(Class<? extends Animal> animalClass, int radius)
163	    {
164	        for(Location where : adjacentLocations(radius)) {
165	            Object animal = getField().getObjectAt(where);
166	            if(animalClass.isInstance(animal)) {
167	                Animal mate = (Animal) animal;
168	                if(mate.getGender() != getGender()) {
169	                    return true;
170	                }
171	            }
172	        }
173	        return false;
174	    }
