176	    /**
177	     * Find the first adjacent location containing a matching target.
178	     */
179	    protected final <T> Location findAdjacentLocation(Class<T> targetClass, int radius,
180	                                                      Predicate<T> predicate)
181	    {
182	        for(Location where : adjacentLocations(radius)) {
183	            Object target = getField().getObjectAt(where);
184	            if(targetClass.isInstance(target)) {
185	                T candidate = targetClass.cast(target);
186	                if(predicate.test(candidate)) {
187	                    return where;
188	                }
189	            }
190	        }
191	        return null;
192	    }
