194	    /**
195	     * Apply an action to each adjacent matching target.
196	     */
197	    protected final <T> void forEachAdjacent(Class<T> targetClass, int radius,
198	                                             Consumer<T> action)
199	    {
200	        for(Location where : adjacentLocations(radius)) {
201	            Object target = getField().getObjectAt(where);
202	            if(targetClass.isInstance(target)) {
203	                action.accept(targetClass.cast(target));
204	            }
205	        }
206	    }
